function compact(n) {
  n = Number(n) || 0;
  if (n < 1000) return String(n);
  if (n < 10000) return (Math.floor(n / 100) / 10).toFixed(1).replace(/\.0$/, '') + 'k';
  if (n < 1000000) return Math.round(n / 1000) + 'k';
  return (Math.round(n / 100000) / 10).toFixed(1).replace(/\.0$/, '') + 'M';
}

